// Hand-written types mirroring the shapes `apps/site`'s components already
// expect (previously generated by `sanity typegen` into sanity.types.ts).
// content.ts normalizes EmDash's REST responses into exactly these shapes so
// every downstream component (ArticleCard.astro, Footer.astro, ...) needed
// zero changes for the CMS swap — only the data-fetching layer changed. See
// docs/emdash-migration-plan.md.

export interface EmdashImage {
  id: string;
  /** Absolute URL — content.ts resolves EmDash's origin-relative media paths against EMDASH_URL. */
  src: string;
  alt: string | null;
  width: number;
  height: number;
}

export interface SectionRef {
  slug: string;
  title: string;
  accentColor: string;
}

export interface SectionData extends SectionRef {
  _id: string;
  tagline: string;
  order: number;
  seo: SeoData | null;
}

export interface AuthorRef {
  slug: string;
  name: string;
  avatar: EmdashImage;
}

export interface AuthorData extends AuthorRef {
  _id: string;
  role: string;
  bio: string;
  twitter?: string | null;
  seo: SeoData | null;
}

export interface SeoData {
  metaTitle?: string | null;
  metaDescription?: string | null;
  ogImage?: EmdashImage | null;
}

// --- Portable Text -----------------------------------------------------
// Same shape as the old Sanity-authored blockContent: EmDash's portableText
// field type is the same open Portable Text spec (portabletext.org) for the
// standard `block` type, so text/heading/quote/list/link/mark rendering
// carries over unchanged. `imageBlock`/`videoEmbed` are content.ts's own
// normalized discriminants for EmDash's native inline-image and HTML/embed
// blocks — see normalizePortableText() in content.ts for the exact mapping
// (flagged there as something to verify against a live instance).

export interface TextSpan {
  _type: "span";
  _key: string;
  text?: string;
  marks?: string[];
}
export interface LinkMarkDef {
  _type: "link";
  _key: string;
  href: string;
  newTab?: boolean;
}
export interface TextBlock {
  _type: "block";
  _key: string;
  style?: "normal" | "h2" | "blockquote";
  listItem?: "bullet" | "number";
  level?: number;
  children?: TextSpan[];
  markDefs?: LinkMarkDef[];
}
export interface ImageBlockData {
  _type: "imageBlock";
  _key: string;
  id: string;
  src: string;
  alt?: string | null;
  caption?: string | null;
  width: number;
  height: number;
}
export interface VideoEmbedData {
  _type: "videoEmbed";
  _key: string;
  url: string;
}
export type BodyBlock = TextBlock | ImageBlockData | VideoEmbedData;

// --- Articles ------------------------------------------------------------

export interface ArticleCardData {
  _id: string;
  slug: string;
  title: string;
  dek: string;
  hero: EmdashImage;
  section: SectionRef | null;
  authors: AuthorRef[];
  publishedAt: string;
  readTime: number;
  premium: boolean;
  featured: boolean;
}

export interface ArticleDetail extends Omit<ArticleCardData, "authors" | "section"> {
  section: SectionRef;
  authors: AuthorData[];
  tags: string[];
  freePreviewBlocks: number;
  body: BodyBlock[];
  seo: SeoData | null;
}

// --- Live blogs ------------------------------------------------------------

export interface LiveBlogSummary {
  _id: string;
  slug: string;
  title: string;
  dek: string;
  startedAt: string;
}

export interface LiveBlogEntryData {
  timestamp: string;
  headline?: string | null;
  body: BodyBlock[];
  author?: AuthorRef | null;
}

export interface LiveBlogDetail extends LiveBlogSummary {
  section: SectionRef | null;
  hero: EmdashImage;
  status: "live" | "ended";
  entries: LiveBlogEntryData[];
  seo: SeoData | null;
}

// --- Site settings ---------------------------------------------------------

export interface NavLinkResolved {
  label: string;
  linkType: "internal" | "external";
  internalHref: string | null;
  externalUrl: string | null;
}

export interface FooterLinkGroupResolved {
  heading: string;
  links: NavLinkResolved[];
}

export interface SocialLink {
  platform: string;
  url: string;
}

export interface SiteSettingsData {
  title: string;
  tagline: string;
  logo: EmdashImage | null;
  defaultSeo: SeoData;
  mainNav: NavLinkResolved[];
  footerLinkGroups: FooterLinkGroupResolved[];
  socialLinks: SocialLink[];
  copyrightText: string | null;
  breakingNews: { active: boolean; headline: string | null; href: string | null } | null;
}
